      // Speculative look-ahead: check if a 2-step extension also completes.
      // If yes, keep generating (promotes combined expressions).
      // If no, close immediately.
      if maxSteps - steps >= 5 {
        var candTok, candPre, hitComp, hitEos, stepsUsed :=
          helpers.SpeculativeConstrainedRollout(
            lm, parser, constrainedPrompt, currentConstrainedOut, 2, eosToken
          );
        steps := steps + stepsUsed;
        if hitComp && !hitEos && maxSteps - steps >= 2 {
          // A longer complete expression is reachable: continue inside the span.
