            var cg2, ci2, cc2 := helpers.CloseConstrainedSpan(
              lm, parser, generated, currentConstrainedOut
            );
            generated := cg2;
            insideConstrainedOut := ci2;
            currentConstrainedOut := cc2;
            steps := steps + 1;
            break;
          } else {
            var ag2, ai2, ac2 := helpers.AppendConstrainedToken(
              lm, parser, generated, currentConstrainedOut, next2
            );
            generated := ag2;
            insideConstrainedOut := ai2;
            currentConstrainedOut := ac2;
          }
        } else {
          // No longer completion reachable: close at current complete state.
          // parser.IsCompletePrefix still holds (speculative rollout didn't
          // change currentConstrainedOut).
          if maxSteps - steps >= 1 {
            var cg3, ci3, cc3 := helpers.CloseConstrainedSpan(
              lm, parser, generated, currentConstrainedOut
            );
            generated := cg3;
            insideConstrainedOut := ci3;
            currentConstrainedOut := cc3;
            steps := steps + 1;
          } else {
            // Absolute budget floor: CloseSpanWithinBudget with 0 budget still
            // safe via postcondition; skip close to avoid budget violation.
            break;
          }
        }
      } else {
        // Low remaining budget: close immediately.
        if maxSteps - steps >= 1 {
          var cg4, ci4, cc4 := helpers.CloseConstrainedSpan(
            lm, parser, generated, currentConstrainedOut
          );
          generated := cg4;
          insideConstrainedOut := ci4;
          currentConstrainedOut := cc4;
          steps := steps + 1;
        } else {
          break;
        }
      }
    } else if maxSteps - steps <= 3 {
      // Near budget end: attempt to close whatever we have.
      var closeBudget := maxSteps - steps;
      var cg5, ci5, cc5 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg5;
      insideConstrainedOut := ci5;
      currentConstrainedOut := cc5;
      steps := maxSteps;
    } else {
      // Normal constrained generation inside the span.
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

